import sys

def insertion_sort(arr):
    for i in range(1, len(arr)):
        key = arr[i]
        j = i - 1
        while j >= 0 and key < arr[j]:
            arr[j + 1] = arr[j]
            j -= 1
        arr[j + 1] = key
    return arr

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    if n == 0:
        print("")
        return
    arr = list(map(int, data[1:n+1]))
    insertion_sort(arr)
    print(' '.join(map(str, arr)))

if __name__ == "__main__":
    main()
